import { Component } from 'react'
import PropTypes from 'prop-types'
import { Modal, CustomText, Button } from '../../../../../components'
import { WALLET_LANG } from '../../constants'
import { VerificationStyle } from './index.style'
import { TASK_LIST_SVG } from '../../../../../images'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { LANG_STRINGS } from '../../../../../lang'

class KTPNPWPVerification extends Component {
  static propTypes = {
    showModal: PropTypes.bool,
    onClose: PropTypes.func
  }

  handleVerifyScreen = (e) => {
    this.props.history.push({
      pathname: '/verify/user/ktp'
    })
  }

  render () {
    const { showModal, onClose } = this.props
    return (
      <Modal
        heading={WALLET_LANG.verificationData}
        isOpen={showModal}
        onClose={onClose}
      >
        <VerificationStyle>
          <div><img src={TASK_LIST_SVG} alt='' /></div>
          <CustomText
            fontSize='16px'
            weight='700'
            paddingTop='10px'
            color={AgentColorPallette.black}
          >
            {WALLET_LANG.verificationData}
          </CustomText>
          <CustomText
            fontSize='14px'
            textAlign='center'
            paddingTop='10px'
            color={AgentColorPallette.fontSecondary}
          >
            {WALLET_LANG.verificationContent}
          </CustomText>
          <Button
            type='button'
            key='verifyBtn'
            onClick={this.handleVerifyScreen}
            className='verifyNowBtn'
          >
            {WALLET_LANG.verifyNow}
          </Button>
          <Button
            type='button'
            key='cancelBtn'
            handleClick={onClose}
            className='cancelBtn'
          >
            {LANG_STRINGS.cancel}
          </Button>
        </VerificationStyle>
      </Modal>
    )
  }
}

export default KTPNPWPVerification
