import { Component } from 'react'
import PropTypes from 'prop-types'
import { WalletHeaderStyle } from './index.style'
import SwitchButton from '../../../../../components/SwitchButton'
import { LANG_STRINGS } from '../../../../../lang'
import { DisplayFlexCCC, Row, DisplayCircleIcon } from '../../../../../commonStyle/index.style'
import { CustomText, Button } from '../../../../../components'
import { formatMoney } from '../../../../../helpers/utility'
import { setToLocalStorage, getFromLocalStorageData } from '../../../../../helpers/localstorage'
import { WALLET_VIEW } from '../../../../../constants/cookies'
import { INFO } from '../../../../../images'
import ToolTip from '../../../../../components/ToolTip'

class WalletHeader extends Component {
  static propTypes = {
    onWithdrawal: PropTypes.func,
    onSwitchView: PropTypes.func,
    point: PropTypes.number,
    comission: PropTypes.number,
    advance: PropTypes.number,
    disabled: PropTypes.bool
  }

  state = {
    activeView: 'commission'
  }

  componentDidMount () {
    if (typeof getFromLocalStorageData(WALLET_VIEW) === 'string') {
      this.handleSwitchBtnChange(getFromLocalStorageData(WALLET_VIEW))
    }
  }

  handleSwitchBtnChange = (view) => {
    // this update the view
    this.setState({
      activeView: view
    })
    setToLocalStorage(WALLET_VIEW, view)
    this.props.onSwitchView(view)
  }

  handleBtnClick = () => {
    // handle the btns on state change
    if (this.state.activeView === 'commission') {
      this.props.onWithdrawal()
    } else {
      this.props.history.push('/point/transition')
    }
  }

  render () {
    const { comission, point, disabled, advance = 0 } = this.props
    const { activeView } = this.state
    const isCommissionView = activeView === 'commission'
    return (
      <WalletHeaderStyle padBottom={!!advance}>
        <SwitchButton
          left={{
            text: LANG_STRINGS.commission,
            value: 'commission'
          }}
          right={{
            text: LANG_STRINGS.point,
            value: 'point'
          }}
          selectedValue={isCommissionView ? 'left' : 'right'}
          className='switch-btn'
          onChange={this.handleSwitchBtnChange}
        />
        <DisplayFlexCCC>
          <CustomText
            weight={800}
            top='8px'
          >
            {isCommissionView ? LANG_STRINGS.myTotalCommission : LANG_STRINGS.myTotalPoint}
          </CustomText>
          <CustomText
            size='20px'
            weight={800}
            bottom='20px'
          >
            {isCommissionView ? formatMoney(comission, 0) : formatMoney(point, 3, '')}
          </CustomText>
          <Button
            className={`withdraw-button ${!!disabled && 'disabled-btn-with-white'}`}
            onClick={this.handleBtnClick}
            disabled={disabled}
          >
            {isCommissionView ? LANG_STRINGS.withdrawal : LANG_STRINGS.convertPoint}
          </Button>
        </DisplayFlexCCC>
        {
          !!advance && (
            <DisplayFlexCCC>
              <Row className='advance-payment' align='center' justify='center'>
                <CustomText
                  weight={800}
                >
                  {LANG_STRINGS.cashAdvanceAmount}&nbsp;:&nbsp;{formatMoney(advance, 0)}
                </CustomText>
                <ToolTip
                  dataView={
                    <CustomText>
                      {LANG_STRINGS.initialBalanceIsGivenAndRestAdjusted}
                    </CustomText>
                  }
                  className='advance-tool-tip'
                  wrapperClassName='advance-info-icon'
                >
                  <DisplayCircleIcon>
                    <img src={INFO} alt='' />
                  </DisplayCircleIcon>
                </ToolTip>
              </Row>
            </DisplayFlexCCC>
          )
        }
      </WalletHeaderStyle>
    )
  }
}

export default WalletHeader
