import { Component } from 'react'
import PropTypes from 'prop-types'
import { SwitchButtonStyle } from './index.style'

class SwitchButton extends Component {
  static propTypes = {
    onChange: PropTypes.func,
    selectedValue: PropTypes.string,
    name: PropTypes.string,
    left: PropTypes.object,
    right: PropTypes.object // {text, value}
  }

  constructor (props) {
    super(props)
    this.state = {
      active: props.selectedValue || 'left'
    }
    this.isUpdatedView = false
  }

  componentWillReceiveProps (nextProps) {
    if (!this.isUpdatedView && (nextProps.selectedValue !== this.state.active)) {
      this.isUpdatedView = true
      this.setState({
        active: nextProps.selectedValue
      })
    }
  }

  componentWillUnmount () {
    this.isUpdatedView = false
  }

  handleSwitchBtn = (btn, btnType) => {
    // this handle switch btn
    this.setState({
      active: btn
    })
    this.isUpdatedView = true
    this.props.onChange(btnType.value)
  }

  render () {
    const { left, right, className } = this.props
    const { active } = this.state

    return (
      <SwitchButtonStyle className={className}>
        <div className='switch-button'>
          <span
            className={`active ${active === 'left' ? 'box-shadow-right' : 'box-shadow-left'}`}
            style={{ left: active === 'left' ? 0 : '50%' }}
          />
          <div
            onClick={e => this.handleSwitchBtn('left', left)}
            className={`switch-button-case ${active === 'left' && 'active-case'}`}
          >
            {left.text}
          </div>
          <div
            onClick={e => this.handleSwitchBtn('right', right)}
            className={`switch-button-case ${active === 'right' && 'active-case'}`}
          >
            {right.text}
          </div>
        </div>
      </SwitchButtonStyle>
    )
  }
}

export default SwitchButton
