import { Component } from 'react'
import { connect } from 'react-redux'
import { get } from 'lodash/object'
import { Container, CustomText, ContentBox, Button } from '../../../components'
import { WalletWrapper } from './index.style'
import { ImageUrl } from '../../../images'
import { formatMoney, isCreditAmount } from '../../../helpers/utility'
import { AgentColorPallette } from '../../../configs/colorPallete'
import { NoContent } from './noContent'
import KTPNPWPVerification from './components/KTPNPWPVerification'
import WalletHeader from './components/WalletHeader'
import TransactionActions from '../../../redux/transaction/action'
import AgentActions from '../../../redux/user/action'
import { Row } from '../../../commonStyle/index.style'
import { getFromLocalStorageData } from '../../../helpers/localstorage'
import { WALLET_VIEW } from '../../../constants/cookies'
import { isEmpty } from 'lodash'

const { getPointsList, getTransactionList } = TransactionActions
const { getAgentDetails } = AgentActions

class Wallet extends Component {
  constructor (props) {
    super(props)
    this.state = {
      isOpenModal: false,
      pageSize: 5,
      isPointView: false // two view one commission / point
    }
    this.isVerifyDocCall = false
    this.pageSize = 5
  }

  componentDidMount () {
    if (isEmpty(getFromLocalStorageData(WALLET_VIEW))) {
      // its called if wallet view not set in the localStorage
      this.props.getTransactionList()
    }
    this.props.getAgentDetails()
  }

  isDocNotVerified = () => {
    const { agentDetails } = this.props
    return (get(agentDetails, 'is_ktp_verified', '') === false)
  }

  handleCloseModal = () => {
    this.setState(prevState => ({
      isOpenModal: !prevState.isOpenModal
    }))
  }

  handleWithdrawal = () => {
    // this function used to show popup
    // if user email, NPWP and KTP not verified
    if (this.isDocNotVerified()) {
      this.setState({
        isOpenModal: true
      })
    } else {
      // if doc verified then move the user to
      // withdrawal screen
      this.props.history.push('/balance/withdrawal')
    }
  }

  handleSwitchView = (view) => {
    if (view === 'point') {
      this.pageSize = 5
      this.setState({
        isPointView: true
      })
      this.props.getPointsList({
        page_size: this.pageSize
      })
    } else {
      this.setState({
        isPointView: false
      })
      this.props.getTransactionList({
        page_size: this.pageSize
      })
    }
  }

  handleLoadMore = () => {
    this.pageSize = this.pageSize + 5
    this.props.getPointsList({
      page_size: this.pageSize
    })
  }

  renderBalanceDetails = (image, text, balance) => {
    return (
      <div className='detail-item'>
        <img src={image} className='image-icon' alt='item' />
        <CustomText textAlign='center' weight='700'>{text}</CustomText>
        <CustomText size='18px' weight='800' textAlign='center'>{balance}</CustomText>
      </div>
    )
  }

  render () {
    const {
      agentDetails, transactionList = {}, pointsList = {}, history,
      pointLoader, transactionLoader, isGuardianAgentLogin
    } = this.props
    const { isPointView } = this.state
    const isBtnPad = (transactionList.data && (transactionList.data.length > 2)) || (pointsList.data && (pointsList.data.length > 2))
    return (
      <Container title='Saldo Saya' loader={pointLoader || transactionLoader} showOJKText>
        <KTPNPWPVerification
          showModal={this.state.isOpenModal}
          onClose={this.handleCloseModal}
          history={history}
        />
        <WalletWrapper bottom={isBtnPad}>
          <WalletHeader
            onWithdrawal={this.handleWithdrawal}
            onSwitchView={this.handleSwitchView}
            comission={agentDetails.wallet_balance}
            point={agentDetails.point_balance}
            advance={agentDetails.advance_balance}
            disabled={!!isGuardianAgentLogin || agentDetails.category === 'LV_ADMIN'}
            history={history}
          />
          <div className='wallet-list'>
            {
              isPointView
                ? (
                  <div className='points-container'>
                    <Row justify='space-between' align='center' className='header'>
                      <CustomText color={AgentColorPallette.black} size='18px' top='14px' bottom='24px' weight='700'>
                        {`${pointsList.meta_data ? pointsList.meta_data.total_records : 0} Mutasi Terakhir`}
                      </CustomText>
                      {
                        pointsList.meta_data && pointsList.meta_data.total_records > 0 &&
                          <img src={ImageUrl.list} alt='list-icon' className='list-image' onClick={() => this.props.history.push('/balance/history/?wallet_type=points')} />
                      }
                    </Row>
                    {
                      pointsList.data && pointsList.data.length > 0
                        ? pointsList.data.map((transaction, index) => (
                          <ContentBox
                            heading={`${transaction.commission_type} ${isCreditAmount(transaction.amount) ? 'setelah Pajak' : ''}`}
                            value={isCreditAmount(transaction.amount) ? `+ ${formatMoney(transaction.amount, 2, '')} P` : `${formatMoney(transaction.amount, 2, '')} P`}
                            secondRowText={transaction.description}
                            thirdRowText={transaction.transaction_date}
                            color={isCreditAmount(transaction.amount) ? AgentColorPallette.green : AgentColorPallette.error}
                            tax={`Pajak: -${formatMoney(transaction.tax, 0)}`}
                            key={index}
                          />
                        ))
                        : !pointLoader && <NoContent />
                    }
                    {
                      pointsList.meta_data && pointsList.meta_data.total_records > (pointsList.data.length) &&
                        <Button className='button-load' onClick={this.handleLoadMore}>
                          {'TAMPILKAN LAGI'}
                        </Button>
                    }
                  </div>
                )
                : (
                  <>
                    <Row justify='space-between' align='center' className='header'>
                      <CustomText color={AgentColorPallette.black} size='18px' top='14px' bottom='24px' weight='700'>
                        {`${transactionList.meta_data ? transactionList.meta_data.total_records : 0} Mutasi Terakhir`}
                      </CustomText>
                      {
                        transactionList.meta_data && transactionList.meta_data.total_records > 0 &&
                          <img src={ImageUrl.list} alt='list-icon' className='list-image' onClick={() => this.props.history.push('/balance/history/?wallet_type=commision')} />
                      }
                    </Row>
                    {
                      transactionList.data && transactionList.data.length > 0
                        ? (
                          transactionList.data.map((transaction, index) => (
                            <ContentBox
                              heading={`${transaction.commission_type} ${isCreditAmount(transaction.amount) ? 'setelah Pajak' : ''}`}
                              value={isCreditAmount(transaction.amount) ? '+ ' + formatMoney(transaction.amount, 0) : formatMoney(transaction.amount, 0)}
                              secondRowText={transaction.description}
                              thirdRowText={transaction.transaction_date}
                              color={isCreditAmount(transaction.amount) ? AgentColorPallette.green : AgentColorPallette.error}
                              tax={`Pajak: -${formatMoney(transaction.tax, 0)}`}
                              key={index}
                            />
                          ))
                        )
                        : (!transactionLoader && <NoContent />)
                    }
                  </>
                )
            }
          </div>
        </WalletWrapper>
      </Container>
    )
  }
}

export default connect(
  (state) => ({
    agentDetails: state.User.agentDetails,
    agentDetailsLoading: state.Loading.GET_USER_DETAILS,
    transactionList: state.Transaction.transactionList,
    pointLoader: state.Loading.GET_POINTS_LIST,
    isGuardianAgentLogin: state.Auth.isGuardianAgentLogin,
    transactionLoader: state.Loading.GET_TRANSACTION_LIST,
    pointsList: state.Transaction.pointsList
  }),
  {
    getPointsList,
    getAgentDetails,
    getTransactionList
  }
)(Wallet)
